#!/bin/bash
#SBATCH --job-name=cob-granite-supervisor
#SBATCH --account=/anonymous/home
#SBATCH --partition=small-g
#SBATCH --time=72:00:00
#SBATCH --nodes=1
#SBATCH --gpus-per-node=1
#SBATCH --cpus-per-task=7
#SBATCH --ntasks-per-node=1
#SBATCH --signal=B:USR1@120
#SBATCH --output=%x-%j.out
#SBATCH --error=%x-%j.err

# generated by src/experiments/v5/slurm.py for backend rocm, profile lumi
# AMD MI250X (gfx90a), 8 GCDs per node, Slurm; every path resolves under COB_PROFILE_ROOT
# backend: torch exposes ROCm through the same torch.cuda namespace; bitsandbytes is still imported by unsloth even when its optimizer is unused, which is the open risk
# layout run, run granite-supervisor-v5-r01
# all three validation evaluations of this attempt must pass --run granite-supervisor-v5-r01:
# selection groups results by an exact match on that string and normalizes nothing

set -euo pipefail

if [ -z "${COB_PROFILE_ROOT:-}" ]; then
  echo "COB_PROFILE_ROOT is not set: it must point at this profile's root (caches, checkpoints, logs)" >&2
  exit 2
fi
mkdir -p "${COB_PROFILE_ROOT}/logs" "${COB_PROFILE_ROOT}/models/training/supervisor/granite/granite-supervisor-v5-r01" "${COB_PROFILE_ROOT}/models/training/supervisor/granite/granite-supervisor-v5-r01/checkpoints"

# site setup
# lmod reaches a batch job as an exported shell function through sbatch
# --export=ALL. source it explicitly if that did not happen, because the failure
# otherwise is "module: command not found" several lines later
if ! type module >/dev/null 2>&1; then
  source "${LMOD_PKG:-/opt/cray/pe/lmod/lmod}/init/bash"
fi
# sbatch propagates the submitting shell's modules, and the PyTorch container
# module declares conflict('singularity-AI-bindings'). a submitter who happened to
# have the bindings loaded therefore got "Cannot load module ... because these
# module(s) are loaded: singularity-AI-bindings", an empty $SIF and an exit 2.
# purging first makes the job independent of whatever state it was submitted from.
# plain purge, not --force: it clears the bindings while leaving LUMI's sticky
# modules in place, and --force would strip those too for no benefit here
module purge
export EBU_USER_PREFIX="${COB_EB_USER_PREFIX:-/project//anonymous/home/EasyBuild}"
module load LUMI/25.03 partition/container
module use "${EBU_USER_PREFIX}/modules/container"
module load PyTorch/2.7.1-rocm-6.2.4-python-3.12-singularity-20250827
if [ -z "${SIF:-}" ]; then
  echo "SIF is empty: the LUMI stack must be loaded before the container module" >&2
  exit 2
fi

# settings only the compute node can resolve, evaluated here and not at generation time
export COB_JOB_CACHE="${TMPDIR:-/tmp}/cob-${SLURM_JOB_ID:-$$}"
mkdir -p "${COB_JOB_CACHE}/unsloth" "${COB_JOB_CACHE}/inductor" \
         "${COB_JOB_CACHE}/triton" "${COB_JOB_CACHE}/aiter" "${COB_JOB_CACHE}/bin"
export UNSLOTH_COMPILE_LOCATION="${COB_JOB_CACHE}/unsloth"
export TORCHINDUCTOR_CACHE_DIR="${COB_JOB_CACHE}/inductor"
export TRITON_CACHE_DIR="${COB_JOB_CACHE}/triton"
# aiter jit-builds kernels at import and defaults its build tree to $HOME/.aiter
export AITER_JIT_DIR="${COB_JOB_CACHE}/aiter"
# node-local and memory-backed: it counts against this job's allocation, so it is released when the job ends
trap 'rm -rf "${COB_JOB_CACHE}"' EXIT

# every path comes from the execution profile, none is hardcoded in the python
export GPU_ARCHS="gfx90a"
export HF_HOME="${COB_PROFILE_ROOT}/hf-cache"
export HF_HUB_CACHE="${COB_PROFILE_ROOT}/hf-cache/hub"
export HF_XET_CACHE="${COB_PROFILE_ROOT}/hf-cache/xet"
export MIOPEN_CUSTOM_CACHE_DIR="${COB_PROFILE_ROOT}/.miopen"
export MIOPEN_USER_DB_PATH="${COB_PROFILE_ROOT}/.miopen"
export PIP_CACHE_DIR="${COB_PROFILE_ROOT}/pip-cache"
export PYTORCH_ROCM_ARCH="gfx90a"
export PYTHONPATH="${PYTHONPATH:-}:$(pwd)"
export COB_DATASET_VERSION=v5

if [ -f "${COB_PROFILE_ROOT}/models/training/supervisor/granite/granite-supervisor-v5-r01/TRAINING_DONE" ]; then
  echo "training already finished, nothing to do"
  exit 0
fi

# the run itself: one continuous 3-epoch run, an adapter saved at every epoch boundary,
# resuming from the newest complete checkpoint if this is a continuation.
#
# recorded caveat, carried here and on every result record (results_store.py
# EPOCH_COMPARABILITY_NOTE): the linear LR schedule decays across the whole 3-epoch
# horizon, so this run's epoch-1 and epoch-2 adapters are NOT directly comparable to v4's
# separately trained epoch-1 and epoch-2 families. compare v5 epochs with each other, and
# v4 against v5 only at the final selected checkpoint.
# errexit is lifted around it on purpose: a non-zero exit is the wall-time case this
# script exists to handle, and under set -e the shell would die before reading it
# one resubmission per job, whoever asks for it. the wall-time trap and the non-zero
# exit path below can both reach this; the guard is what stops them queueing two
# successors for the same job
COB_RESUBMITTED=0
cob_resubmit() {
  if [ "$COB_RESUBMITTED" -ne 0 ]; then return 0; fi
  COB_RESUBMITTED=1
  attempt="${COB_CONTINUATION:-0}"
  if [ "$attempt" -ge "12" ]; then
    echo "reached 12 continuations without finishing, stopping" >&2
    return 1
  fi
  export COB_CONTINUATION=$((attempt + 1))
  echo "resubmitting continuation $COB_CONTINUATION"
  sbatch --dependency=afterany:${SLURM_JOB_ID} --export=ALL "$0"
}

# Slurm signals the batch shell shortly before the wall clock. resubmit from here, then
# stop the trainer and leave cleanly: the successor picks up from the newest checkpoint
cob_on_walltime() {
  echo "wall time approaching, resubmitting before the kill"
  cob_resubmit || true
  kill "${train_pid:-0}" 2>/dev/null || true
  exit 0
}
trap cob_on_walltime USR1

COB_INNER="${COB_JOB_CACHE:-${TMPDIR:-/tmp}}/cob-inner-${SLURM_JOB_ID:-$$}.sh"
# the training command, staged to a file so it can run in the background
cat > "$COB_INNER" <<'COB_CONTAINER'
set -euo pipefail
# singularity resets PATH, so anything prepended on the host is gone by here. aiter
# locates a compiler by shelling out to `which c++` literally, which HIP_CLANG_PATH
# does not satisfy; the container has no c++/g++/gcc/cc on PATH but does ship a real
# compiler as ROCm clang. without this the job dies inside accelerate's deepspeed
# import with a FileNotFoundError deep in aiter's build tree, naming no compiler
export HIP_CLANG_PATH="${ROCM_PATH:-/opt/rocm}/llvm/bin"
ln -sf "${HIP_CLANG_PATH}/clang++" "${COB_JOB_CACHE}/bin/c++"
ln -sf "${HIP_CLANG_PATH}/clang++" "${COB_JOB_CACHE}/bin/g++"
ln -sf "${HIP_CLANG_PATH}/clang" "${COB_JOB_CACHE}/bin/cc"
ln -sf "${HIP_CLANG_PATH}/clang" "${COB_JOB_CACHE}/bin/gcc"
export PATH="${COB_JOB_CACHE}/bin:${PATH}"
source "${COB_PROFILE_ROOT}/unsloth-env/bin/activate"
# fail here rather than after minutes of setup. it runs in this same container
# process, so the aiter build it triggers is the one the training run then reuses
python -c "import torch, unsloth" || {
  echo "venv at ${COB_PROFILE_ROOT}/unsloth-env cannot import torch+unsloth" >&2
  exit 91
}
python src/experiments/finetune_lora.py --dataset v5_supervisor --max-seq-length 2048 --batch-size 8 --grad-accum 2 --base-model "${COB_PROFILE_ROOT}/models/base/granite" --instruction-part '<|start_of_role|>user<|end_of_role|>' --response-part '<|start_of_role|>assistant<|end_of_role|>' --lora-targets q_proj,k_proj,v_proj,o_proj,gate_proj,up_proj,down_proj --save-steps 250 --num-train-epochs 3 --save-epoch-adapters --resume --optim adamw_torch --output-dir "${COB_PROFILE_ROOT}/models/training/supervisor/granite/granite-supervisor-v5-r01" --checkpoint-dir "${COB_PROFILE_ROOT}/models/training/supervisor/granite/granite-supervisor-v5-r01/checkpoints"
COB_CONTAINER

# backgrounded on purpose: `wait` is interruptible, a synchronous call is not, and this
# shell has to stay free to run the trap above while training is still going
set +e
singularity exec "$SIF" bash -s < "$COB_INNER" &
train_pid=$!
wait "$train_pid"; status=$?
# wait returns >128 when a handled signal interrupts it, so go back to waiting
while [ "$status" -gt 128 ] && kill -0 "$train_pid" 2>/dev/null; do
  wait "$train_pid"; status=$?
done
set -e

if [ $status -eq 0 ]; then
  touch "${COB_PROFILE_ROOT}/models/training/supervisor/granite/granite-supervisor-v5-r01/TRAINING_DONE"
  echo "training finished"
  exit 0
fi

# died for some other reason: continue from the last checkpoint
cob_resubmit || exit 1

